// Nó Code "Montar jogos do dia" (modo: Run Once for All Items)
// Junta os jogos da football-data e da ESPN, converte para o horário de Brasília,
// fica só com os jogos de hoje e marca o peso de cada time a partir da tabela Times.

const TZ = 'America/Sao_Paulo';
const hoje = $now.setZone(TZ).toFormat('yyyy-MM-dd');

// O nó do Airtable devolve os campos soltos no item; este helper aceita os dois formatos.
const campos = (item) => ({ id: item.json.id, ...(item.json.fields ?? item.json) });

// Campeonatos ativos, indexados pelo código usado na API
const campeonatos = {};
for (const c of $('Campeonatos').all().map(campos)) {
  if (c.Ativo) campeonatos[c['Código']] = c;
}

// Peso dos times: cada grafia em "Nomes nas APIs" aponta para o time
const semAcento = (s) => (s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().trim();
const times = new Map();
for (const t of $('Times').all().map(campos)) {
  for (const nome of (t['Nomes nas APIs'] ?? '').split(',')) {
    if (nome.trim()) times.set(semAcento(nome), { nome: t.Nome, peso: t.Peso ?? 1 });
  }
}
const acharTime = (...nomes) => {
  for (const n of nomes) {
    const t = times.get(semAcento(n));
    if (t) return t;
  }
  return null;
};

const jogos = [];
const adicionar = (codigo, jogo) => {
  const c = campeonatos[codigo];
  if (!c) return;
  const inicio = DateTime.fromISO(jogo.utc, { zone: 'utc' }).setZone(TZ);
  if (inicio.toFormat('yyyy-MM-dd') !== hoje) return;
  const pesoMandante = jogo.timeMandante?.peso ?? 0;
  const pesoVisitante = jogo.timeVisitante?.peso ?? 0;
  jogos.push({
    id: jogo.id,
    campeonato: c.Nome,
    campeonatoId: c.id,
    codigo,
    bloco: c.Bloco,
    ordem: c.Ordem ?? 99,
    todosOsJogos: !!c['Todos os jogos'],
    limiteNota4: c['Limite nota 4'] ?? 0,
    horario: inicio.toFormat('HH:mm'),
    horarioISO: inicio.toISO(),
    mandante: jogo.mandante,
    visitante: jogo.visitante,
    idMandante: jogo.idMandante ?? null,
    idVisitante: jogo.idVisitante ?? null,
    pesoMandante,
    pesoVisitante,
    pesoTotal: pesoMandante + pesoVisitante,
    status: jogo.status,
    fase: jogo.fase ?? null,
    rodada: jogo.rodada ?? null,
  });
};

// football-data.org
const statusFD = {
  SCHEDULED: 'Agendado', TIMED: 'Agendado', IN_PLAY: 'Ao vivo', PAUSED: 'Ao vivo',
  FINISHED: 'Encerrado', AWARDED: 'Encerrado', POSTPONED: 'Adiado', SUSPENDED: 'Adiado', CANCELLED: 'Cancelado',
};
for (const m of $('football-data').first().json.matches ?? []) {
  adicionar(m.competition.code, {
    id: `fd-${m.id}`,
    utc: m.utcDate,
    mandante: m.homeTeam.shortName ?? m.homeTeam.name,
    visitante: m.awayTeam.shortName ?? m.awayTeam.name,
    idMandante: m.homeTeam.id,
    idVisitante: m.awayTeam.id,
    timeMandante: acharTime(m.homeTeam.name, m.homeTeam.shortName),
    timeVisitante: acharTime(m.awayTeam.name, m.awayTeam.shortName),
    status: statusFD[m.status] ?? m.status,
    fase: m.stage,
    rodada: m.matchday,
  });
}

// ESPN (só Europa League). Se a ESPN falhar, o nó segue sem esses jogos.
const statusESPN = (s) => {
  if (s.name === 'STATUS_POSTPONED') return 'Adiado';
  if (s.name === 'STATUS_CANCELED') return 'Cancelado';
  return { pre: 'Agendado', in: 'Ao vivo', post: 'Encerrado' }[s.state] ?? s.name;
};
const espn = $('ESPN').first().json;
for (const ev of espn.events ?? []) {
  const lados = ev.competitions[0].competitors;
  const casa = lados.find((l) => l.homeAway === 'home').team;
  const fora = lados.find((l) => l.homeAway === 'away').team;
  adicionar(espn.leagues?.[0]?.slug ?? 'uefa.europa', {
    id: `espn-${ev.id}`,
    utc: ev.date,
    mandante: casa.shortDisplayName ?? casa.displayName,
    visitante: fora.shortDisplayName ?? fora.displayName,
    timeMandante: acharTime(casa.displayName, casa.shortDisplayName),
    timeVisitante: acharTime(fora.displayName, fora.shortDisplayName),
    status: statusESPN(ev.status.type),
  });
}

jogos.sort((a, b) => a.ordem - b.ordem || a.horarioISO.localeCompare(b.horarioISO));

return [{ json: { data: hoje, total: jogos.length, jogos, espnFalhou: !!espn.error } }];

// Nó Code "Ligas com classificação" (modo: Run Once for All Items)
// Gera um item por campeonato que tem jogo hoje e tem tabela de classificação.
// Mata-mata (ex.: Libertadores na fase final) não tem tabela, então fica de fora.
// Ligue "Always Output Data" nas Settings: assim o fluxo segue mesmo sem nenhuma liga.

const { jogos } = $('Montar jogos do dia').first().json;
const fasesComTabela = ['REGULAR_SEASON', 'LEAGUE_STAGE', 'GROUP_STAGE'];

const codigos = new Set(
  jogos
    .filter((j) => j.id.startsWith('fd-') && fasesComTabela.includes(j.fase))
    .map((j) => j.codigo),
);

return [...codigos].map((codigo) => ({ json: { codigo } }));

// Nó Code "Preparar pedido ao Gemini" (modo: Run Once for All Items)
// Junta cada jogo com a posição dos times na tabela e monta o corpo da chamada ao Gemini,
// pedindo a resposta em JSON com formato fixo (responseSchema).

const { data, jogos } = $('Montar jogos do dia').first().json;

// Posição de cada time por campeonato (o Bayern tem uma posição na Bundesliga e outra na Champions)
const tabela = new Map();
for (const item of $('Classificação').all()) {
  const codigo = item.json.competition?.code;
  for (const s of item.json.standings ?? []) {
    if (s.type !== 'TOTAL') continue;
    for (const linha of s.table) {
      tabela.set(`${codigo}:${linha.team.id}`, `${linha.position}º de ${s.table.length}, ${linha.points} pts em ${linha.playedGames} jogos`);
    }
  }
}

const lista = jogos.map((j) => ({
  id: j.id,
  campeonato: j.campeonato,
  fase: j.fase ?? undefined,
  rodada: j.rodada ?? undefined,
  horario: j.horario,
  mandante: j.mandante,
  visitante: j.visitante,
  tabelaMandante: tabela.get(`${j.codigo}:${j.idMandante}`),
  tabelaVisitante: tabela.get(`${j.codigo}:${j.idVisitante}`),
  pesoMandante: j.pesoMandante,
  pesoVisitante: j.pesoVisitante,
}));

const instrucoes = `Você é editor de pauta de um canal de esportes brasileiro.
Para cada jogo, dê uma nota de relevância de 1 a 5 para o público brasileiro e escreva um briefing.

Critérios da nota:
5 = jogão: clássico ou rivalidade histórica, confronto direto entre times do topo da tabela, decisão (mata-mata, final) ou time brasileiro decidindo título ou vaga.
4 = jogo bom: pelo menos um time gigante (peso 3) ou confronto entre times da parte de cima da tabela.
3 = interessante só para quem acompanha o campeonato.
2 = jogo comum.
1 = pouco relevante.

O peso dos times vem de uma lista mantida pela produção: 3 = gigante, 2 = forte, 0 = sem destaque.

Regras:
- Use os dados de tabela fornecidos. Não invente resultados recentes, lesões, artilheiros, técnicos ou escalações.
- Brasileirão e Libertadores interessam mais ao público: na dúvida, suba a nota.
- "motivo": uma frase curta explicando a nota.
- "briefing": no máximo 2 frases, em português do Brasil, dizendo o que está em jogo. Tom de jornalista esportivo, sem exagero.
- Avalie todos os jogos recebidos e devolva cada um com o mesmo id.`;

const body = {
  systemInstruction: { parts: [{ text: instrucoes }] },
  contents: [{ role: 'user', parts: [{ text: `Jogos de ${data}:\n${JSON.stringify(lista, null, 1)}` }] }],
  generationConfig: {
    temperature: 0.4,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        jogos: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              id: { type: 'STRING' },
              nota: { type: 'INTEGER' },
              motivo: { type: 'STRING' },
              briefing: { type: 'STRING' },
            },
            required: ['id', 'nota', 'motivo', 'briefing'],
          },
        },
      },
      required: ['jogos'],
    },
  },
};

return [{ json: { totalJogos: jogos.length, body } }];

// Nó Code "Selecionar jogos" (modo: Run Once for All Items)
// Lê as notas do Gemini e aplica as regras do resumo:
// - campeonatos com "Todos os jogos" marcado: entram todos;
// - nos outros: nota 5 entra sempre, nota 4 entra até o "Limite nota 4" do campeonato.
// Se o Gemini falhar, a nota sai do peso dos times e o resumo é enviado mesmo assim.

const { data, jogos } = $('Montar jogos do dia').first().json;

let avaliacoes = [];
let llmFalhou = false;
try {
  const resposta = $('Gemini').first().json;
  const texto = resposta.candidates[0].content.parts.map((p) => p.text ?? '').join('');
  avaliacoes = JSON.parse(texto).jogos;
} catch (e) {
  llmFalhou = jogos.length > 0;
}
const porId = new Map(avaliacoes.map((a) => [a.id, a]));

const notaPeloPeso = (j) => {
  if (j.pesoTotal >= 5) return 5;
  if (j.pesoTotal >= 4 || Math.max(j.pesoMandante, j.pesoVisitante) === 3) return 4;
  if (j.pesoTotal >= 2) return 3;
  return 2;
};

const avaliados = jogos.map((j) => {
  const a = porId.get(j.id);
  const nota = Number.isInteger(a?.nota) ? Math.min(5, Math.max(1, a.nota)) : notaPeloPeso(j);
  return {
    ...j,
    nota,
    motivo: a?.motivo ?? 'Nota calculada pelo peso dos times (sem LLM).',
    briefing: a?.briefing ?? '',
  };
});

const porCampeonato = new Map();
for (const j of avaliados) {
  if (!porCampeonato.has(j.codigo)) porCampeonato.set(j.codigo, []);
  porCampeonato.get(j.codigo).push(j);
}

const escolhidos = [];
for (const lista of porCampeonato.values()) {
  if (lista[0].todosOsJogos) {
    escolhidos.push(...lista);
    continue;
  }
  escolhidos.push(...lista.filter((j) => j.nota === 5));
  const nota4 = lista
    .filter((j) => j.nota === 4)
    .sort((a, b) => b.pesoTotal - a.pesoTotal || a.horarioISO.localeCompare(b.horarioISO));
  escolhidos.push(...nota4.slice(0, lista[0].limiteNota4));
}

escolhidos.sort((a, b) => a.ordem - b.ordem || a.horarioISO.localeCompare(b.horarioISO));

return [{
  json: {
    data,
    llmFalhou,
    totalAnalisados: jogos.length,
    totalEscolhidos: escolhidos.length,
    jogos: escolhidos,
  },
}];

// Nó Code "Separar jogos" (modo: Run Once for All Items)
// Transforma a lista de jogos escolhidos em um item por jogo,
// com as chaves iguais aos nomes das colunas da tabela Jogos no Airtable.

const { jogos } = $('Selecionar jogos').first().json;

return jogos.map((j) => ({
  json: {
    ID: j.id,
    Data: j.horarioISO.slice(0, 10),
    'Horário': j.horarioISO,
    Campeonato: [j.campeonatoId],
    Mandante: j.mandante,
    Visitante: j.visitante,
    Status: j.status,
    Nota: j.nota,
    'Por que a nota': j.motivo,
    Briefing: j.briefing,
  },
}));

// Nó Code "Montar mensagem" (modo: Run Once for All Items)
// Monta o resumo do dia em HTML do Telegram, uma mensagem por bloco (Brasil, Copas, Europa).
// O Telegram aceita até 4096 caracteres por mensagem; se um bloco passar disso, ele é dividido.

const LIMITE = 3900;
const { data, jogos, llmFalhou, totalAnalisados } = $('Selecionar jogos').first().json;
const espnFalhou = $('Montar jogos do dia').first().json.espnFalhou;

const html = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const selo = (nota) => (nota === 5 ? '🔥' : nota === 4 ? '⭐' : '▫️');
const dia = DateTime.fromISO(data).setLocale('pt-BR').toFormat("cccc, dd/MM");

const blocos = [
  { nome: 'Brasil', titulo: '🇧🇷 <b>BRASIL</b>' },
  { nome: 'Copas', titulo: '🏆 <b>COPAS</b>' },
  { nome: 'Europa', titulo: '🌍 <b>EUROPA</b>' },
];

const cabecalho = jogos.length
  ? `📅 <b>Pauta de hoje: ${html(dia)}</b>\n${jogos.length} de ${totalAnalisados} jogos selecionados · 🔥 jogão · ⭐ bom jogo`
  : `📅 <b>Pauta de hoje: ${html(dia)}</b>\nHoje não tem jogos dos campeonatos acompanhados.`;

const avisos = [];
if (llmFalhou) avisos.push('⚠️ O Gemini não respondeu hoje: notas calculadas pelo peso dos times, sem briefing.');
if (espnFalhou) avisos.push('⚠️ A ESPN não respondeu: a Europa League pode estar faltando.');

const mensagens = [];
let atual = cabecalho;
const fechar = () => { if (atual.trim()) mensagens.push(atual); atual = ''; };
const adicionar = (trecho) => {
  if (atual && (atual + '\n\n' + trecho).length > LIMITE) fechar();
  atual = atual ? `${atual}\n\n${trecho}` : trecho;
};

for (const bloco of blocos) {
  const doBloco = jogos.filter((j) => j.bloco === bloco.nome);
  if (!doBloco.length) continue;
  if (mensagens.length || atual !== cabecalho) fechar();
  adicionar(bloco.titulo);
  let campeonatoAtual = null;
  for (const j of doBloco) {
    const linhas = [];
    if (j.campeonato !== campeonatoAtual) {
      linhas.push(`<u>${html(j.campeonato)}</u>`);
      campeonatoAtual = j.campeonato;
    }
    linhas.push(`${selo(j.nota)} <b>${j.horario}</b> · ${html(j.mandante)} x ${html(j.visitante)}`);
    if (j.briefing) linhas.push(`<i>${html(j.briefing)}</i>`);
    adicionar(linhas.join('\n'));
  }
}
if (avisos.length) adicionar(avisos.join('\n'));
fechar();

return mensagens.map((texto) => ({ json: { texto } }));
